<script>
const csrf=<?=json_encode($csrf, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
const command=document.getElementById('command'),send=document.getElementById('send'),voice=document.getElementById('voice'),plan=document.getElementById('plan'),response=document.getElementById('response'),agents=document.getElementById('agents'),errorBox=document.getElementById('errorBox'),history=document.getElementById('history'),apiStatus=document.getElementById('apiStatus'),openaiConnector=document.getElementById('openaiConnector'),adminConnector=document.getElementById('adminConnector'),metaConnector=document.getElementById('metaConnector'),whatsappConnector=document.getElementById('whatsappConnector'),charCount=document.getElementById('charCount');
function setStatus(text,kind){apiStatus.textContent=text;apiStatus.className='status '+kind}function badge(el,text,kind){el.textContent=text;el.className='badge '+kind}function error(message){errorBox.textContent=message;errorBox.classList.toggle('show',!!message)}function addHistory(text,state){if(history.querySelector('.empty'))history.innerHTML='';const row=document.createElement('div');row.className='history-item';row.textContent=new Date().toLocaleTimeString()+' — '+state+': '+text.slice(0,120);history.prepend(row)}
function renderPlan(data,orchestrator,specialists){response.className='response';response.textContent=data.goal+'\n\nRisk: '+data.risk_level+'\nMissing information: '+(data.missing_information.length?data.missing_information.join('; '):'None')+'\nApprovals required: '+(data.approvals_required.length?data.approvals_required.map(x=>x.type+': '+x.reason).join('; '):'None');plan.innerHTML='';data.steps.forEach(s=>{const li=document.createElement('li');const b=document.createElement('b');b.textContent='Step '+s.step_number+' — '+s.agent;const d=document.createElement('div');d.className='muted';d.textContent=s.action;li.append(b,d);plan.appendChild(li)});agents.innerHTML='';const owner=document.createElement('div');owner.className='agent';const on=document.createElement('span');on.textContent='Business Owner';const os=document.createElement('span');os.className='agent-state active';os.textContent='Active orchestrator';owner.append(on,os);agents.appendChild(owner);const specialistMap=new Map((Array.isArray(specialists)?specialists:[]).map(x=>[x.name,x.status]));const names=[...new Set(['Product Manager',...data.required_agents.filter(name=>name!=='Business Owner')])];names.forEach(name=>{const row=document.createElement('div');row.className='agent';const n=document.createElement('span');n.textContent=name;const st=document.createElement('span');const state=specialistMap.get(name);if(state==='active'){st.className='agent-state active';st.textContent='Active specialist'}else if(state==='ready'){st.className='agent-state planned';st.textContent='Ready specialist'}else{st.className='agent-state planned';st.textContent='Planned only'}row.append(n,st);agents.appendChild(row)})}
async function health(){try{const r=await fetch('/rainbow-ai/health.php',{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!d.ok)throw new Error('Health check failed');badge(adminConnector,d.security.admin_configured?(d.security.authenticated?'Authenticated':'Login Required'):'Not Configured',d.security.authenticated?'ok':(d.security.admin_configured?'warn':'bad'));badge(openaiConnector,d.openai.connected?'Connected':(d.openai.configured?'Configured / Locked':'Not Connected'),d.openai.connected?'ok':(d.openai.configured?'warn':'bad'));if(d.meta&&d.meta.connected){const a=d.meta.account||{};badge(metaConnector,'Connected'+(a.name?' · '+a.name:''),'ok')}else badge(metaConnector,'Not Connected','bad');if(d.whatsapp&&d.whatsapp.connected){const w=d.whatsapp.phone||{};badge(whatsappConnector,'Connected'+(w.verified_name?' · '+w.verified_name:''),'ok')}else badge(whatsappConnector,'Not Connected','bad');if(d.openai.connected&&d.meta&&d.meta.connected&&d.whatsapp&&d.whatsapp.connected)setStatus('Business Owner Active · Systems Connected','connected');else setStatus('Connection Check Incomplete','failed')}catch(e){badge(openaiConnector,'Health Check Failed','bad');badge(metaConnector,'Health Check Failed','bad');badge(whatsappConnector,'Health Check Failed','bad');setStatus('Connection Check Failed','failed')}}
command.addEventListener('input',()=>charCount.textContent=command.value.length+' / 4000');send.addEventListener('click',async()=>{const text=command.value.trim();error('');if(text.length<3){error('Enter a command of at least 3 characters.');return}send.disabled=true;voice.disabled=true;send.textContent='Sending…';setStatus('Business Owner routing…','loading');try{const r=await fetch('/rainbow-ai/orchestrate.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({command:text})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Command failed.');renderPlan(d.plan,d.orchestrator,d.specialists);addHistory(text,'Business Owner routed plan');const pm=Array.isArray(d.specialists)&&d.specialists.some(x=>x.name==='Product Manager'&&x.status==='active');setStatus(pm?'Product Manager Active · Plan ready':'Business Owner Active · Plan ready','connected')}catch(e){response.className='empty';response.textContent='No plan received.';error(e.message||'Command failed.');addHistory(text,'Failed');setStatus('Request Failed','failed')}finally{send.disabled=false;voice.disabled=false;send.textContent='Send Command'}});
const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR){voice.addEventListener('click',()=>{const r=new SR();r.lang='en-IN';r.interimResults=false;voice.disabled=true;voice.textContent='Listening…';r.onresult=e=>{command.value=e.results[0][0].transcript;command.dispatchEvent(new Event('input'))};r.onend=()=>{voice.disabled=false;voice.textContent='Voice Input'};r.start()})}else{voice.disabled=true;voice.textContent='Voice Input unavailable'}health();
</script></body></html>
